########## packs/aws-sam/cloudfront-authorization.mjs
import { finding } from '../../engine/checks/helpers/findings.mjs';
import { samResources } from '../../engine/checks/helpers/sam-templates.mjs';

// Converted from the aws-sam prose (issue #136): a custom
// AWS::CloudFront::OriginRequestPolicy listing Authorization is rejected at deploy
// ("The parameter Headers contains Authorization that is not allowed"). Use the
// managed AllViewerExceptHostHeader policy plus a cache policy that omits it.
// Blocking — the deploy fails otherwise.
//
// FP guard (from adversarial mining): scoped to the policy resource's own Headers,
// so Authorization elsewhere (an API Gateway authorizer's IdentitySource) is fine.
const rule = {
  id: 'aws-sam/cloudfront-authorization',
  severity: 'blocking',
  description: "A custom CloudFront OriginRequestPolicy may not list Authorization in its headers",
  doc: 'packs/aws-sam/RULES.md',
  why: 'CloudFront rejects a custom origin-request policy that forwards Authorization at deploy time',

  run(ctx) {
    const out = [];
    for (const { templatePath, name, resource } of samResources(ctx)) {
      if (resource.Type !== 'AWS::CloudFront::OriginRequestPolicy') continue;
      const headers = resource.Properties
        ?.OriginRequestPolicyConfig?.HeadersConfig?.Headers;
      if (Array.isArray(headers) && headers.some((h) => String(h).toLowerCase() === 'authorization')) {
        out.push(finding(rule, {
          file: templatePath,
          what: `${name}: custom OriginRequestPolicy lists Authorization in its headers`,
          fix: 'drop Authorization from the custom policy and attach the managed AllViewerExceptHostHeader policy (id b689b0a8-53d0-40ab-baf2-68738e2966ac) to forward it, with a cache policy that omits it from the cache key',
        }));
      }
    }
    return out;
  },
};

export default rule;
########## packs/aws-sam/esbuild-dependency.mjs
import { finding } from '../../engine/checks/helpers/findings.mjs';

// Converted from the aws-sam pack prose: SAM's esbuild builder runs a
// production-only npm install, so a devDependency esbuild is skipped and the
// build fails with "Cannot find esbuild." Blocking — it breaks the build.
const rule = {
  id: 'aws-sam/esbuild-dependency',
  severity: 'blocking',
  description: 'esbuild must be a regular dependency, not a devDependency, for SAM esbuild builds',
  doc: 'packs/aws-sam/RULES.md',
  why: "SAM's esbuild builder runs a production-only npm install, so a devDependency esbuild is skipped and the build fails",

  run(ctx) {
    const usesEsbuild = ctx.tracked.some((f) => {
      if (!/(^|\/)template\.ya?ml$/.test(f)) return false;
      const t = ctx.read(f);
      return t !== null && /BuildMethod:\s*esbuild/.test(t);
    });
    if (!usesEsbuild) return [];

    // Single-package repos only: with more than one package.json this is a
    // multi-package repo where the SAM function may build from a different
    // manifest, and a root devDependency esbuild for other tooling is legitimate
    // (an adversarial-mining false positive). Skip rather than misfire.
    if (ctx.tracked.filter((f) => f.endsWith('package.json')).length !== 1) return [];

    const pkgText = ctx.read('package.json');
    if (pkgText === null) return [];
    let pkg;
    try { pkg = JSON.parse(pkgText); } catch { return []; }

    const inDev = pkg.devDependencies?.esbuild;
    const inDeps = pkg.dependencies?.esbuild;
    if (inDev && !inDeps) {
      return [finding(rule, {
        file: 'package.json',
        what: 'esbuild is a devDependency, but SAM BuildMethod: esbuild needs it as a regular dependency',
        fix: 'move esbuild into "dependencies" (SAM\'s build runs a production-only npm install), or put it on the runner PATH before `sam build`',
      })];
    }
    return [];
  },
};

export default rule;
########## packs/aws-sam/handler-path.mjs
import { finding } from '../../engine/checks/helpers/findings.mjs';
import { samResources } from '../../engine/checks/helpers/sam-templates.mjs';

// Converted from the aws-sam prose (issue #136): under BuildMethod: esbuild with a
// single subdirectory entry point and no OutBase, esbuild's default outbase is the
// entry's own dir, so the subdirectory is dropped from the artifact — the Handler
// must not carry it (`handler.handler`, not `src/handler.handler`). Wrong value
// fails only at first invoke with Runtime.ImportModuleError. Blocking.
//
// FP guards (from adversarial mining): skip when OutBase is set (it changes the
// drop) or when there is more than one entry point (behavior differs).
const rule = {
  id: 'aws-sam/handler-path',
  severity: 'blocking',
  description: 'A SAM esbuild single-entry Handler must not carry the entry subdirectory',
  doc: 'packs/aws-sam/RULES.md',
  why: "esbuild's default outbase is the entry's own dir, so the subdir is stripped from the artifact and a subdir Handler fails at invoke",

  run(ctx) {
    const out = [];
    for (const { templatePath, name, resource } of samResources(ctx)) {
      if (resource.Type !== 'AWS::Serverless::Function') continue;
      const meta = resource.Metadata;
      if (!meta || meta.BuildMethod !== 'esbuild') continue;
      const bp = meta.BuildProperties;
