##### packs/github-actions/pages-artifact-symlinks.mjs
import { finding } from '../../engine/checks/helpers/findings.mjs';
import { workflowFiles } from '../../engine/checks/helpers/github-workflows.mjs';

// A GitHub Pages deploy that uploads the repo root fails in CI because
// Claudinite mounts its skills as symlinks (.claude/skills/* -> the gitignored
// .claudinite/ corpus, which is empty on a runner since the sync hook never runs
// there). actions/upload-pages-artifact tars with --dereference, which follows
// the dangling links and errors — silently blocking every deploy. The fix is to
// prune the agent-tooling dirs from the artifact before upload.
const rule = {
  id: 'gha/pages-artifact-symlinks',
  severity: 'blocking',
  description: 'A GitHub Pages artifact that uploads the repo root must prune the agent-tooling dirs (their skill symlinks dangle in CI)',
  doc: 'bootstrap.md',
  why: 'upload-pages-artifact tars with --dereference and fails on the dangling .claude/skills/* symlinks, blocking every deploy',

  run(ctx) {
    // The hazard exists only where the skills are mounted as symlinks into the
    // gitignored corpus: .claude/skills/* is tracked, .claudinite/skills/* is not,
    // so those links dangle on a fresh CI checkout.
    const mountsSkillSymlinks =
      ctx.tracked.some((f) => /^\.claude\/skills\//.test(f)) &&
      !ctx.tracked.some((f) => /^\.claudinite\/skills\//.test(f));
    if (!mountsSkillSymlinks) return [];

    const out = [];
    for (const wf of workflowFiles(ctx)) {
      const text = ctx.read(wf);
      if (text === null) continue;
      if (!/uses:\s*actions\/upload-pages-artifact/.test(text)) continue;
      // Only the whole-tree upload (path: .) drags the dangling links into the
      // tar; a dedicated build dir (the action's default, or path: _site) is safe.
      if (!/^\s*path:\s*['"]?\.\/?['"]?\s*$/m.test(text)) continue;
      // A step that removes the tooling dirs before upload defuses it.
      if (/\brm\b[^\n]*\.claude/.test(text)) continue;
      out.push(finding(rule, {
        file: wf,
        what: 'uploads the repo root (path: .) to actions/upload-pages-artifact, but .claude/skills/* are symlinks into the gitignored .claudinite/ corpus (empty in CI) — they dangle and the action tars with --dereference, so the deploy fails',
        fix: 'add a step before the upload that prunes the agent tooling: `run: rm -rf .claude .claudinite` (never part of a published site)',
      }));
    }
    return out;
  },
};

export default rule;
##### packs/github-actions/no-scheduled-fleet-executor.mjs
import { finding } from '../../engine/checks/helpers/findings.mjs';
import { workflowFiles } from '../../engine/checks/helpers/github-workflows.mjs';

// One schedule per repo. Which schedule depends on whether the repo has cut over to
// the per-repo scheduler (per-project-scheduling §3, §8):
//
// - **Cut over** (the vendored `claudinite-scheduler.yml` is present): that workflow
//   is the repo's ONE permitted cron, and any other `schedule:` is a competing cron.
//   The recurring work moves INTO a scheduler task — its steps become the task's
//   worker and the workflow is deleted. It is NOT converted to a dispatch-only
//   workflow that a task then fires: that keeps two files and two places to edit
//   for one job, and leaves a workflow whose only caller is the thing that replaced
//   it. A task IS the recurring unit after cutover, not a dispatcher for leftovers.
//   This stricter rule travels WITH the scheduler into a repo's mount — never before
//   it, so a repo mid-cutover is never falsely flagged for the crons it is about to
//   retire.
// - **Not yet cut over** (no scheduler workflow, i.e. a repo still adopting): the repo has
//   no sanctioned Claudinite cron yet, so only a scheduled Claudinite *executor* — a
//   workflow that calls a canon reusable @main — is flagged, as the shape that competes
//   with the scheduler the repo is about to vendor. A consumer's own unrelated scheduled
//   workflow is not flagged.
const SCHEDULER_WORKFLOW = '.github/workflows/claudinite-scheduler.yml';

const rule = {
  id: 'gha/no-scheduled-fleet-executor',
  severity: 'blocking',
  description: 'The vendored claudinite-scheduler.yml is the repo\'s only permitted cron once present — a competing cron\'s work moves into a scheduler task and the workflow goes; before it is vendored, a Claudinite executor (one that calls a canon reusable) must be workflow_dispatch-only',
  doc: 'packs/basics/scheduled-tasks.md',
  why: 'a second cron competes with the one schedule the repo is meant to have — the per-repo scheduler, which owns every recurring Claudinite job',

  run(ctx) {
    const out = [];
    const cutOver = ctx.read(SCHEDULER_WORKFLOW) !== null;
    for (const wf of workflowFiles(ctx)) {
      if (wf === SCHEDULER_WORKFLOW) continue; // the scheduler itself is the permitted cron
      const text = ctx.read(wf);
      if (text === null) continue;
      if (!/^\s*schedule:/m.test(text)) continue;
      if (cutOver) {
        // The scheduler is the repo's only cron; every other recurring workflow is
        // dispatch-only (a scheduler task fires it).
        out.push(finding(rule, {
          file: wf,
          what: 'carries a `schedule:` trigger, but the vendored claudinite-scheduler.yml is this repo\'s only permitted cron',
          fix: 'port this workflow\'s steps into the scheduler task that owns the work and delete the workflow in the same commit — after cutover a task IS the recurring unit, so do not leave a dispatch-only workflow behind for a task to fire (per-project-scheduling §3)',
        }));
        continue;
      }
      // Pre-cutover: only a scheduled canon-reusable executor competes with the fleet routine.
      if (!/uses:\s*\S*\/Claudinite\/\.github\/workflows\//i.test(text)) continue;
      out.push(finding(rule, {
        file: wf,
